from pathlib import Path
import hashlib,io,json,tarfile
R=Path('/Users/lanxingcan/Workspace/zstdoxize');C=Path('/private/tmp/zstdoxide-tree-tiny-2026-10-13')
sha=lambda b:hashlib.sha256(b).hexdigest();enc=lambda v:(json.dumps(v,sort_keys=True,indent=2)+'\n').encode()
e=json.loads((C/'evidence.json').read_text())
if e['status']!='passed' or e['source_before']!=e['source_after']:raise ValueError('completed unchanged capture')
files={str(p.relative_to(C)):p for p in C.rglob('*') if p.is_file()}
chunks={};mapping={}
for name,p in sorted(files.items()):
 if p.is_symlink():raise ValueError('no symlink')
 b=p.read_bytes();keys=[]
 for offset in range(0,len(b),4096):
  block=b[offset:offset+4096];h=sha(block);chunks[h]=block;keys.append(h)
 mapping[name]=dict(bytes=len(b),sha256=sha(b),chunks=keys)
report=dict(status='passed',capture_evidence_sha256=sha((C/'evidence.json').read_bytes()),raw_files=len(files),raw_bytes=sum(v['bytes'] for v in mapping.values()),archive='2026-10-13-tree-tiny.tar.gz',chunk_bytes=4096,qualification='Complete capture including original requests, stdout/stderr, objects and executables. Downloaded upstream sources remain external. All archived members and reconstructed files checked without executing archived code.')
reconstruct=Path('/tmp/package-zstdoxide-double-fast-frames.py').read_text().split("reconstruct='''",1)[1].split("'''",1)[0]
members={'file-map.json':enc(mapping),'report.json':enc(report),'reconstruct.py':reconstruct.encode(),**{'chunks/'+h+'.bin':b for h,b in chunks.items()}}
a=R/'docs/evidence'/report['archive']
if a.exists():raise ValueError('fresh archive')
with tarfile.open(a,'w:gz') as t:
 for n,b in sorted(members.items()):
  i=tarfile.TarInfo('tree-tiny/'+n);i.size=len(b);i.mode=0o644;t.addfile(i,io.BytesIO(b))
with tarfile.open(a) as t:found={m.name:t.extractfile(m).read() for m in t}
if found!={'tree-tiny/'+n:b for n,b in members.items()}:raise ValueError('archive members')
for name,item in mapping.items():
 b=b''.join(found['tree-tiny/chunks/'+h+'.bin'] for h in item['chunks'])
 if len(b)!=item['bytes'] or sha(b)!=item['sha256'] or b!=files[name].read_bytes():raise ValueError('reconstruction '+name)
report.update(archive_bytes=a.stat().st_size,archive_sha256=sha(a.read_bytes()),archive_members=len(members),verified_files=len(mapping));Path('/tmp/zstdoxide-tree-tiny-archive.json').write_bytes(enc(report));print(report['raw_files'],report['raw_bytes'],report['archive_bytes'])

